WITH valid AS (SELECT *, SUBSTRING(status, 1, 4) AS status_prefix, QUARTER(paid_at) AS paid_at_quarter, COALESCE(method, 'N/A') AS resolved_method FROM payments WHERE paid_at >= TO_TIMESTAMP('2023-09-24 14:00:00')) SELECT id, order_id, method, amount, status, status_prefix, MIN(amount) OVER (PARTITION BY DATE_TRUNC('WEEK', paid_at), order_id) AS paid_at_period_min_amount, LAST_VALUE(amount, TRUE) OVER (ORDER BY paid_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS last_known_amount, ROW_NUMBER() OVER w_hist AS row_seq FROM valid WINDOW w_hist AS (ORDER BY paid_at DESC, id);
